AND (Q.IS_ISSUE_ASSET IS NULL OR Q.IS_ISSUE_ASSET = 'N')
UNION ALL select interf.SECID id, interf.secname text, fin.FINPROD_ID, interf.SECNAME FINPROD_NAME, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null from interf_payhsrcsecinfo interf left join fin_product fin on interf.SECID = fin.FINPROD_ID where SECID not in (select FINPROD_MARKET_ID from fin_product A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG}
AND B.TYPE_4 = #{windtypeone}
)
AND interf.SECID = #{initValue}
AND interf.MARKET in
