and ( interf.SECID LIKE CONCAT('%', CONCAT(#{search}, '%')) or interf.SECNAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

select count(1)
from FIN_EXERCISE_PLAN
where
    FINPROD_ID = #{finprodId}
    and EXERCISE_DATE > = #{sysDate,jdbcType=DATE}

select count(1)
from FIN_EXERCISE_PLAN
where
    FINPROD_ID = #{finprodId}

    and ACT_EXERCISE_DATE = #{paramDate,jdbcType=DATE}

SELECT
       100 - NVL(sum(fcp.PRIN_AMT), 0)
FROM
     FIN_CASH_PLAN fcp
     inner join FIN_CASH_INFO fci
     on fcp.CASH_ID = fci.CASH_ID
WHERE
    fcp.FINPROD_ID = #{finprodId}

    AND fcp.MDATE <= #{settleDate}
    and fci.CASH_TYPE_1 = #{cashType1}


where
    FINPROD_ID = #{finprodId}
    and FINPROD_TYPE2 = #{finprodType}
order by EFF_DATE

        select
            TDY_INTINCEXP as tdyIntincexp,
            SHARE_AMT as shareAmt
        from
            PTL_SEC_VALUTION
        where
             PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
          and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
          and INV_AIM = #{invAim,jdbcType=VARCHAR}
          and CDATE =
           (
              select
                max(CDATE)
              from
                PTL_SEC_VALUTION
              where
                PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
	          and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
	          and INV_AIM = #{invAim,jdbcType=VARCHAR}
            )

	         SELECT T.PORTFOLIO_ID id, T.PORTFOLIO_NAME text
  				FROM PTL_PORTFOLIO T
  				LEFT JOIN PTL_SEC_ACCT PSA
    				ON T.PORTFOLIO_ID = PSA.PORTFOLIO_ID
 				WHERE PSA.ACCT_NO=#{secManageAcctId,jdbcType=VARCHAR}

                	AND T.PORTFOLIO_ID = #{initValue}


                AND ( T.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%'))
                or
                T.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))
                )

select DEALNO DEALNO, SECID SECID, PROFOLIO_ID PROFOLIO_ID, CCY CCY, INVTYPE INVTYPE, PS PS, PRICE_8 PRICE_8, YIELD_8 YIELD_8, CNO CNO, FACEAMT FACEAMT,
TRD_MATCH_INFO.MATCH_NUM PRINAMT,
PRINAMT PRINAMT,
SETTAMT SETTAMT, PRODUCT PRODUCT, PRODTYPE PRODTYPE, TRAD TRAD, CONVINTAMT CONVINTAMT, EFFECTFLAG EFFECTFLAG, BROK BROK, INPUTDATE INPUTDATE, DEALDATE DEALDATE, SETTDATE SETTDATE, REVDATE REVDATE, UPDATECOUNTER UPDATECOUNTER, FEDEALNO FEDEALNO, DEALTEXT DEALTEXT, LSTMNTDATE LSTMNTDATE, CLIENTTRADER CLIENTTRADER, STRIKEYIELD STRIKEYIELD, DIRTYPRICE DIRTYPRICE, SETTLE_SPEED, UNIT_INT, OURDEPOSITACCOUNTNUMBER, COUNTERTELEPHONE from INTERF_TRAD_SECDEAL
inner join TRD_MATCH_INFO on TRD_MATCH_INFO.CSTP_TRADE_ID = INTERF_TRAD_SECDEAL.Fedealno
and INTERF_TRAD_SECDEAL.FEDEALNO = #{fedealno}
and TRD_MATCH_INFO.Entrust_Id=#{entrustId}
and TRD_MATCH_INFO.PRE_TRADE_ID=#{preTradeId}

