  AMOUNT
from PTL_CASH_POSITION
where
 (HODING_TYPE=#{POSITION_TYPE_01} or HODING_TYPE=#{POSITION_TYPE_03}) and PORTFOLIO_ID=#{portfolioId}
 and CDATE= #{platDate,jdbcType=DATE} and CHL_FINPROD_ID=#{TongDao}

select

from TRD_PRODUCT_DEAL where 1=1

    and f_trade_id=#{fTradeId}

and IS_CANCEL='N' AND TRADE_STATUS =01
and FINPROD_TYPE2 = #{finprodType2}

select TRADE_AMT
from WFL_TRD_PRODUCT_DEAL
where 1=1

    and f_trade_id=#{fTradeId}


    and workflow_id != #{workflowId}

and IS_CANCEL='N' AND TRADE_STATUS =01
and FINPROD_TYPE2 = #{finprodType2}

SELECT T1.COUNTER_ID id, T1.COUNTER_NAME text FROM MST_COUNTER_PARTY T1
( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND T1.COUNTER_ID = #{initValue}
AND T1.COUNTER_TYPE = #{counterType}

        SELECT
            fp.FINPROD_ID finprodId, 
            round(t.DSC_CLEAN_PRICE_B,4) dscprice, round(VALUATION_INFO.NETPRICE,4) netprice
        FROM fin_product fp		
        left join (
        	select t.SEC_ID,	
                   t.NETPRICE						
            from (select t.*,							
                        row_number() over(partition by t.SEC_ID order by t.VALUE_DATE desc) as rnum							
                   from MST_BOND_VALUATION_INFO t							
                  where VALUE_DATE <= to_date(#{tradeDate}, 'yyyy-MM-dd')-1) t							
        	where rnum = 1
        ) VALUATION_INFO on fp.FINPROD_MARKET_ID = VALUATION_INFO.SEC_ID
        left join (
        select FINPROD_ID,DSC_CLEAN_PRICE_B,PORTFOLIO_ID,INV_AIM
	        from ptl_sec_valution
	        where cdate = to_date(#{tradeDate}, 'yyyy-MM-dd')-1
	            and PORTFOLIO_ID = #{portfolioId}
	            and FINPROD_ID = #{finprodId}
	            and INV_AIM = #{invAim} 

                	AND SEC_ACCT_ID = #{chlId}

	            ) t 
        ON 	t.FINPROD_ID = fp.FINPROD_ID			
        where
            fp.FINPROD_ID = #{finprodId}

select t.finprod_id finprodId,t.share_amt shareAmt,t.yield,t.ps from trd_product_deal t left JOIN trd_product_deal_add tpda on t.TRADE_ID=tpda.TRADE_ID left JOIN fin_product_type fpt on t.finprod_id=fpt.finprod_id and t.branch=fpt.branch where t.finprod_id=#{finprodId}
AND tpda.PORTFOLIO_ID IN
#{item}
and to_date(#{date},'yyyy-MM-dd')=t.TRADE_DATE and fpt.type_8='F01'and t.trade_status='01'and t.is_cancel='N' and t.ps in('T01','T02') order by t.UPDATE_TIME asc

select t.pos_amount posAmount ,t.cost_rate costRate,t.FAIRE_PRICE fairePrice from  ASSET_TARGET_DB  t  where t.cdate=to_date(#{date},'yyyy-MM-dd')
and t.finprod_id=#{finprodId}

    and t.IS_PERNE= #{pass}

and rownum=1

with temp as ( SELECT distinct T.CHL_ID FROM TRD_PRODUCT_DEAL T LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPDA.TRADE_ID = T.TRADE_ID
LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = T.FINPROD_ID
WHERE T.IS_CANCEL = 'N' AND T.TRADE_STATUS IN ( '01' , '03' ) AND T.PS = 'HK09' AND T.CHL_ID = #{chlId,jdbcType=VARCHAR}
AND TPDA.PORTFOLIO_ID = #{finprodId,jdbcType=VARCHAR}
AND FPA.PORTFOLIO_ID = #{counterId,jdbcType=VARCHAR}
) select case when t.PAY_TYPE = '01' Then 1 when t.PAY_TYPE = '02' and t.CHL_ID is not null then 1 else 0 end as count from ( SELECT distinct FPA.PAY_TYPE,FP.FINPROD_ID,Tp.CHL_ID FROM FIN_PRODUCT FP LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = FP.FINPROD_ID left join temp tp on Tp.CHL_ID = FP.FINPROD_ID WHERE FP.IS_CHL = 'Y' and FP.FINPROD_ID = #{chlId,jdbcType=VARCHAR} )t

SELECT T1.PORTFOLIO_ID, T3.PROFIT_TYPE FROM IBU_QUOTE_BOND T1 INNER JOIN IBU_QUOTE_BOND_DET T2 ON T2.QUOTE_ID = T1.QUOTE_ID INNER JOIN PTL_PORTFOLIO T3 ON T3.PORTFOLIO_ID = T1.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T4 ON T3.PORTFOLIO_ID = T4.PORTFOLIO_ID
AND T4.USER_ID = #{loginUserName}
WHERE T2.EXECID = #{fedealno}

choose.when:
SELECT PP.PORTFOLIO_NAME AS portfolioId, /*产品名称*/ SCI1.BUSI_ACCT_NO AS busiAcctNo,/*资金账号*/ TO_CHAR(TPD.TRADE_DATE,'yyyy-MM-dd') AS tradeDate, /*业务日期*/ FP.FINPROD_MARKET_ID AS finprodMarketId, /*证券代码*/ FP.FINPROD_ABBR AS finprodAbbr, /*证券名称*/ SDL1.ITEM_VALUE AS secType,/*证券类别*/ SDL.ITEM_VALUE AS psStr, /*本方方向*/ SDL2.ITEM_VALUE AS entrustStatus,/*委托状态*/ SDL3.ITEM_VALUE AS tradePlat,/*业务分类*/ SDL4.ITEM_VALUE AS entrustType, /*投资类型*/ SDL5.ITEM_VALUE AS priceModel,/*价格类型*/ EE.PRICE AS price,/*委托价格*/ EE.ENTRUST_NUM AS entrustNum,/*委托数量*/ EE.ENTRUST_AMT AS entrustAmt,/*委托金额*/ ROUND(NVL(T5.FINISH_AMT,0)*100/(EE.ENTRUST_NUM*100),4)*100 AS transactioncom,/*成交度*/ TPD.UNIT_CPRICE AS unitCprice,/*成交均价*/ TPD.UNIT_FPRICE AS unitFprice,/*成交全价*/ TPD.SHARE_AMT AS shareAmt,/*成交数量*/ TPD.TRADE_AMT AS tradeAmt, /*成交金额*/ SU1.REAL_NAME AS traderName,/*下达人姓名*/ SU2.REAL_NAME AS invManagerName,/*指令下达人姓名*/ EEA.COUNTER_SEAT AS counterSeat,/*对手席号*/ EEA.COUNTER_CON_NO AS counterConNo,/*约定号*/ EE.COUNTER_TRADER AS counterTrader /*对手交易员*/ FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON TPD.TOTLE_TRADE_ID = TOTAL.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT FP ON TPD.FINPROD_ID = FP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO PP ON TOTAL.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_PAY_ORDERS SPO ON TPD.TRADE_ID = SPO.TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON TOTAL.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO SCI1 ON NVL(SPO.MY_ACCT_NO,SAI.TRD_ACCT_ID) = SCI1.ACCT_NO LEFT JOIN SYS_DATADICT_LIST SDL ON SDL.ITEM_CODE = TPD.PS AND SDL.DICT_CODE = 'PS' LEFT JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN SYS_DATADICT_LIST SDL1 ON FPT.TYPE_10 = SDL1.ITEM_CODE AND SDL1.DICT_CODE = 'CUSTOM_ASSET_TYPE_THREE' LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPD.TRADE_ID = TPDA.TRADE_ID LEFT JOIN ETR_ENTRUST EE ON TPDA.ENTRUST_ID = EE.ENTRUST_ID LEFT JOIN SYS_DATADICT_LIST SDL2 ON EE.ENTRUST_STATUS = SDL2.ITEM_CODE AND SDL2.DICT_CODE = 'ENTRUST_STATUS' LEFT JOIN SYS_DATADICT_LIST SDL3 ON TPD.TRADE_PLAT = SDL3.ITEM_CODE AND SDL3.DICT_CODE = 'SHARES_TRADE_PLATFORM' LEFT JOIN SYS_DATADICT_LIST SDL4 ON EE.ENTRUST_TYPE = SDL4.ITEM_CODE AND SDL4.DICT_CODE = 'ENTRUST_OPERATE_TYPE' LEFT JOIN SYS_DATADICT_LIST SDL5 ON EE.PRICE_MODEL = SDL5.ITEM_CODE AND SDL5.DICT_CODE = 'PRICE_MODEL' LEFT JOIN ( SELECT ENTRUST_ID, SUM( FINISH_AMT ) AS FINISH_AMT FROM ETR_FINISH_STATUS WHERE ENTRUST_ID != TRADE_ID GROUP BY ENTRUST_ID ) T5 ON EE.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.ENTRUST_ID = EEA.ENTRUST_ID LEFT JOIN SYS_USER SU1 ON TOTAL.TRADER = SU1.USER_NAME LEFT JOIN SYS_USER SU2 ON EE.INV_MANAGER_ID = SU2.USER_NAME WHERE TPD.FINPROD_TYPE = 'F01' AND TPD.IS_CANCEL != 'Y'
AND TPD.TRADE_MARKET IN
#{item,jdbcType=VARCHAR}
AND (TPD.TOTLE_TRADE_ID IN
null) OR TPD.TOTLE_TRADE_ID IN (
#{item,jdbcType=VARCHAR}
)

choose.otherwise:
SELECT TOTAL.PORTFOLIO_ID, /*组合代码*/ TPD.TOTLE_TRADE_ID, /*成交编号*/ FP.FINPROD_MARKET_ID, /*资产代码*/ FP.FINPROD_ABBR, /*资产简称*/ SDL.ITEM_VALUE AS psStr, /*本方方向*/ PP.PORTFOLIO_NAME AS BF, /*本方*/ MST_COUNTER_PARTY.COUNTER_NAME, /*对手方*/ TPD.COUNTER_TRADER, /*对手方交易员*/ TO_CHAR(TPD.SETTLE_DATE,'yyyy-MM-dd') settleDate, /*结算日，交割日*/ SDL1.ITEM_VALUE AS deliveryType, /*结算方式*/ NVL(TPD.SHARE_AMT,0)/10000*100 shareAmt, /* 券面*/ TPD.YIELD*100 yield , /*到期收益率*/ TPD.EXER_YIELD*100 exerYield, /*行权收益率*/ TPD.UNIT_INT, TPD.INT_AMT, /*利息总额，应计利息*/ TPD.UNIT_CPRICE, /*单位净价*/ TPD.FPRICE_AMT, /*全价总额*/ TPD.TRADE_AMT, /*结算金额*/ DECODE(TOTAL.SETTLE_SPEED,NULL,'',CONCAT('T+',TOTAL.SETTLE_SPEED)) sttleSpeed, /*清算速度*/ SDL1.ITEM_VALUE AS CLEAR_TYPE /*清算类型*/ FROM TRD_PRODUCT_DEAL TPD LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON TPD.TOTLE_TRADE_ID = TOTAL.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT FP ON TPD.FINPROD_ID = FP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO PP ON TOTAL.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN SYS_DATADICT_LIST SDL ON TPD.PS = SDL.ITEM_CODE AND SDL.DICT_CODE = 'PS' LEFT JOIN MST_COUNTER_PARTY ON TPD.COUNTER_ID = MST_COUNTER_PARTY.COUNTER_ID LEFT JOIN SYS_DATADICT_LIST SDL1 ON TOTAL.DELIVERY_TYPE = SDL1.ITEM_CODE AND SDL1.DICT_CODE = 'SETT_MODE' LEFT JOIN SYS_DATADICT_LIST SDL2 ON TOTAL.CLEAR_TYPE = SDL2.ITEM_CODE AND SDL2.DICT_CODE = 'CLEAR_TYPE' WHERE TPD.FINPROD_TYPE = 'F01' AND TPD.IS_CANCEL != 'Y'
AND TPD.TRADE_MARKET IN
#{item,jdbcType=VARCHAR}
AND (TPD.TOTLE_TRADE_ID IN
null) OR TPD.TOTLE_TRADE_ID IN (
#{item,jdbcType=VARCHAR}
)
